INSERT INTO public.dev_tasks(id,payload) VALUES
('platform-34',jsonb_build_object('id','platform-34','title','Verify real recovery and invitation email links','description','Callback completion supports SDK initialization, token_hash and PKCE without duplicate exchange; Site URL fallback routes password intent to reset. 27 tests pass. Blocked: real valid email link and external Supabase URL Configuration settings cannot be verified with available managed sessions. Owner must allow exact preview /reset-password URL and future published URL; test newest recovery and invite email without sharing tokens.','area','Auth','priority','P0','status','blocked','impact',5,'effort',2,'rank',64,'createdAt','2026-10-31')),
('platform-35',jsonb_build_object('id','platform-35','title','Brand hosted Supabase authentication emails','description','External Supabase owns auth email templates. Customize recovery, invite, confirmation, email change and other enabled auth notices in Authentication Email Templates with MyOwnMuseum branding, accessible white background, Spanish/English copy and intact ConfirmationURL. Hosted settings are not accessible through available tools. No Lovable sender domain configured; app emails require an owned verified sender domain. Do not activate payments or bulk mail.','area','Auth','priority','P1','status','blocked','impact',4,'effort',2,'rank',65,'createdAt','2026-10-31')),
('platform-36',jsonb_build_object('id','platform-36','title','Collector notification center','description','Implemented private notification table, owner read-state-only grants/RLS, account welcome/museum creation/visibility/plan-interest triggers, unread badge, bilingual list, filters, pagination and read/unread actions. Anonymous protection and database privileges checked. Signed-in end-to-end verification remains blocked by external unmanaged session access.','area','UX','priority','P1','status','done','impact',4,'effort',3,'rank',66,'createdAt','2026-10-31'))
